(()=>{
 const CLIPS={"emerge": "data:audio/wav;base64,", "hit": "data:audio/wav;base64,", "semenych0": "data:audio/wav;base64,", "semenych1": "data:audio/wav;base64,", "semenych2": "data:audio/wav;base64,", "glebas": "data:audio/wav;base64,", "mirosh": "data:audio/wav;base64,", "domik": "data:audio/wav;base64,", "egor": "data:audio/wav;base64,", "drew0": "data:audio/wav;base64,", "edik0": "data:audio/wav;base64,", "edik1": "data:audio/wav;base64,", "edik2": "data:audio/wav;base64,", "bodya0": "data:audio/wav;base64,", "bodya1": "data:audio/wav;base64,", "tema0": "data:audio/wav;base64,", "tema1": "data:audio/wav;base64,", "yarik": "data:audio/wav;base64,", "iiist0": "data:audio/wav;base64,", "iiist2": "data:audio/wav;base64,", "kostyan0": "data:audio/wav;base64,", "kostyan1": "data:audio/wav;base64,", "kostyan2": "data:audio/wav;base64,", "explosion": "data:audio/wav;base64,"};
 let muted=false,lastPop=-Infinity;
 const pending=new Map(),pools={};
 for(const [name,url] of Object.entries(CLIPS)){
  pools[name]=Array.from({length:2},()=>{
   const audio=new Audio(url);audio.preload='auto';audio.playsInline=true;
   audio.preservesPitch=true;
   if('webkitPreservesPitch' in audio)audio.webkitPreservesPitch=true;
   audio.playbackRate=(name==='mirosh'||name.startsWith('drew'))?1.2:name==='domik'?1.5:1;
   audio.setAttribute('playsinline','');
   return {audio,priming:null,unlocked:false,busy:false};
  });
 }
 const volume=name=>name==='emerge'?.7:1;
 const prime=slot=>{
  if(slot.unlocked||slot.priming||slot.busy)return;
  const audio=slot.audio;audio.muted=true;
  slot.priming=Promise.resolve(audio.play()).then(()=>{
   audio.pause();audio.currentTime=0;slot.unlocked=true;
  }).catch(()=>{}).finally(()=>{audio.muted=muted;slot.priming=null;});
 };
 const playClip=(name,requested=performance.now())=>{
  if(muted||document.hidden||performance.now()-requested>250)return;
  const pool=pools[name];
  const slot=pool.find(s=>!s.busy&&!s.priming)||pool.find(s=>!s.busy)||pool[0];
  if(slot.priming){slot.priming.then(()=>playClip(name,requested));return;}
  const audio=slot.audio;audio.pause();audio.currentTime=0;audio.muted=muted;audio.volume=volume(name);
  slot.busy=true;audio.onended=()=>{slot.busy=false;};
  Promise.resolve(audio.play()).then(()=>{slot.unlocked=true;pending.delete(name);}).catch(()=>{
   slot.busy=false;
   if(performance.now()-requested<=250)pending.set(name,requested);
  });
 };
 const unlock=()=>{
  // Each HTML audio element is primed by the native touch gesture, as music is.
  for(const pool of Object.values(pools))for(const slot of pool)prime(slot);
  for(const [name,time] of pending){pending.delete(name);playClip(name,time);}
 };
 for(const event of ['pointerdown','touchstart','touchend','keydown']){
  document.addEventListener(event,unlock,{capture:true,passive:true});
 }
 window.addEventListener('bandwhack-play',unlock);
 const stopAll=()=>{
  pending.clear();
  for(const pool of Object.values(pools))for(const slot of pool){slot.audio.pause();slot.busy=false;}
 };
 window.addEventListener('bandwhack-mute',event=>{
  muted=event.detail.muted;
  for(const pool of Object.values(pools))for(const slot of pool)slot.audio.muted=muted;
  if(muted)stopAll();
 });
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAll();});
 window.addEventListener('bandwhack-emerge',()=>{
  const now=performance.now();if(muted||now-lastPop<70)return;lastPop=now;playClip('emerge');
 });
 document.addEventListener('bandwhack-explosion',()=>playClip('explosion'));
 document.addEventListener('bandwhack-hit',event=>{
  if(muted)return;
  playClip('hit');
  if(event.detail?.character==='Semenych')playClip('semenych'+Math.floor(Math.random()*3));
  if(event.detail?.character==='Mirosh')playClip('mirosh');
  if(event.detail?.character==='Bodya')playClip(Math.random()<.25?'bodya0':'bodya1');
  if(event.detail?.character==='Tema')playClip('tema'+Math.floor(Math.random()*2));
  if(event.detail?.character==='Yarik')playClip('yarik');
  if(event.detail?.character==='Kostyan'){const pick=Math.random();playClip(pick<.5?'kostyan0':pick<.75?'kostyan1':'kostyan2');}
  if(event.detail?.character==='iiist')playClip(Math.random()<.5?'iiist0':'iiist2');
  if(event.detail?.character==='Egor')playClip('egor');
  if(event.detail?.character==='Drew')playClip('drew0');
  if(event.detail?.character==='Edik')playClip('edik'+Math.floor(Math.random()*3));
  if(event.detail?.character==='Domik')playClip('domik');
  if(event.detail?.character==='Glebas')playClip('glebas');
 });
})();
